def parse_query_pairs(text: str) -> dict[str, str]:
    if text == "":
        return {}
    result = {}
    for field in text.split("&"):
        if "=" not in field:
            raise ValueError("each field must contain an equals sign")
        key, value = field.split("=", 1)
        if key == "":
            raise ValueError("keys must not be empty")
        result[key] = value
    return result

import re


def parse_semver(text: str) -> tuple[int, int, int]:
    if re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", text) is None:
        raise ValueError("expected major.minor.patch")
    major, minor, patch = text.split(".")
    return int(major), int(minor), int(patch)

import re


def hex_to_rgb(text: str) -> tuple[int, int, int]:
    if re.fullmatch(r"#[0-9a-fA-F]{6}", text) is None:
        raise ValueError("expected #RRGGBB")
    return int(text[1:3], 16), int(text[3:5], 16), int(text[5:7], 16)

import shlex


def split_quoted_words(text: str) -> list[str]:
    try:
        return shlex.split(text, comments=False, posix=True)
    except ValueError as exc:
        raise ValueError(str(exc)) from exc

def slugify_ascii(text: str) -> str:
    pieces = []
    pending_separator = False
    for ch in text:
        is_ascii_alnum = ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ("0" <= ch <= "9")
        if is_ascii_alnum:
            if pending_separator and pieces:
                pieces.append("-")
            pieces.append(ch.lower())
            pending_separator = False
        else:
            pending_separator = True
    return "".join(pieces)

def mask_email(address: str) -> str:
    if address.count("@") != 1:
        raise ValueError("address must contain exactly one at sign")
    local, domain = address.split("@")
    if local == "" or domain == "":
        raise ValueError("local and domain parts must not be empty")
    if len(local) == 1:
        masked_local = "*"
    elif len(local) == 2:
        masked_local = local
    else:
        masked_local = local[0] + "*" * (len(local) - 2) + local[-1]
    return masked_local + "@" + domain

def tally_values(items: list) -> dict:
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts

def invert_unique(mapping: dict) -> dict:
    result = {}
    for key, value in mapping.items():
        if value in result:
            raise ValueError('mapping values must be unique')
        result[value] = key
    return result

def chunk_list(items: list, size: int) -> list:
    if size <= 0:
        raise ValueError('size must be positive')
    return [items[start:start + size] for start in range(0, len(items), size)]

def merge_counts(left: dict, right: dict) -> dict:
    result = dict(left)
    for key, value in right.items():
        result[key] = result.get(key, 0) + value
    return result

def rotate_left(items: list, steps: int) -> list:
    if not items:
        return []
    offset = steps % len(items)
    return items[offset:] + items[:offset]

def remove_indices(items: list, indices: list) -> list:
    excluded = {index for index in indices if 0 <= index < len(items)}
    return [item for index, item in enumerate(items) if index not in excluded]

def group_by_length(words: list) -> dict:
    result = {}
    for word in words:
        result.setdefault(len(word), []).append(word)
    return result

def nested_get(data: dict, path: list, default: object = None) -> object:
    current = data
    for key in path:
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

from datetime import date

def days_between(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days

from datetime import date, timedelta

def add_business_days(day: str, count: int) -> str:
    current = date.fromisoformat(day)
    step = 1 if count >= 0 else -1
    remaining = abs(count)
    while remaining:
        current += timedelta(days=step)
        if current.weekday() < 5:
            remaining -= 1
    return current.isoformat()

def format_duration(seconds: int) -> str:
    if seconds < 0:
        raise ValueError('seconds must be nonnegative')
    hours, remainder = divmod(seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    return f'{hours}:{minutes:02d}:{secs:02d}'

from datetime import date, timedelta

def next_weekday(day: str, weekday: int) -> str:
    if not 0 <= weekday <= 6:
        raise ValueError('weekday must be from 0 through 6')
    current = date.fromisoformat(day)
    offset = (weekday - current.weekday()) % 7
    if offset == 0:
        offset = 7
    return (current + timedelta(days=offset)).isoformat()

def shift_clock_time(value: str, minutes: int) -> str:
    if len(value) != 5 or value[2] != ':' or not (value[:2].isdigit() and value[3:].isdigit()):
        raise ValueError('time must be HH:MM')
    hour = int(value[:2])
    minute = int(value[3:])
    if hour > 23 or minute > 59:
        raise ValueError('time out of range')
    total = (hour * 60 + minute + minutes) % 1440
    return f'{total // 60:02d}:{total % 60:02d}'

def split_cents(total_cents: int, people: int) -> list[int]:
    base, extra = divmod(total_cents, people)
    return [base + (1 if i < extra else 0) for i in range(people)]

from decimal import Decimal, ROUND_HALF_UP

def percent_change(old: float, new: float) -> float:
    result = (Decimal(str(new)) - Decimal(str(old))) * Decimal('100') / Decimal(str(old))
    return float(result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

from decimal import Decimal, ROUND_HALF_UP

def weighted_mean(values: list[float], weights: list[float]) -> float:
    total = sum(Decimal(str(v)) * Decimal(str(w)) for v, w in zip(values, weights))
    weight_total = sum(Decimal(str(w)) for w in weights)
    result = total / weight_total
    return float(result.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP))

from decimal import Decimal, ROUND_HALF_UP

def compound_balance(principal: float, annual_rate: float, years: int) -> float:
    p = Decimal(str(principal))
    rate = Decimal(str(annual_rate)) / Decimal('100')
    result = p * (Decimal('1') + rate) ** years
    return float(result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def is_valid_username(text: str) -> bool:
    if not isinstance(text, str) or not 3 <= len(text) <= 16:
        return False
    letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    allowed = letters + "0123456789_"
    return text[0] in letters and text[-1] in letters + "0123456789" and all(ch in allowed for ch in text)

def is_valid_simple_email(text: str) -> bool:
    if not isinstance(text, str) or text.count("@") != 1:
        return False
    local, domain = text.split("@")
    alnum = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    if not 1 <= len(local) <= 64:
        return False
    if local[0] not in alnum or local[-1] not in alnum:
        return False
    if ".." in local or any(ch not in alnum + "._-" for ch in local):
        return False
    labels = domain.split(".")
    if len(labels) < 2:
        return False
    for label in labels:
        if not 1 <= len(label) <= 63:
            return False
        if label[0] not in alnum or label[-1] not in alnum:
            return False
        if any(ch not in alnum + "-" for ch in label):
            return False
    return True

def is_valid_hex_color(text: str) -> bool:
    if not isinstance(text, str) or len(text) != 7 or text[0] != "#":
        return False
    return all(ch in "0123456789abcdefABCDEF" for ch in text[1:])

def is_valid_ipv4(text: str) -> bool:
    if not isinstance(text, str):
        return False
    parts = text.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not 1 <= len(part) <= 3 or not part.isascii() or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True

def is_valid_slug(text: str) -> bool:
    if not isinstance(text, str) or not 1 <= len(text) <= 40:
        return False
    alnum = "abcdefghijklmnopqrstuvwxyz0123456789"
    if text[0] not in alnum or text[-1] not in alnum or "--" in text:
        return False
    return all(ch in alnum + "-" for ch in text)

from datetime import date

def is_valid_iso_date(text: str) -> bool:
    if not isinstance(text, str) or len(text) != 10:
        return False
    if text[4] != "-" or text[7] != "-":
        return False
    pieces = (text[:4], text[5:7], text[8:])
    if any(not piece.isascii() or not piece.isdigit() for piece in pieces):
        return False
    year, month, day = map(int, pieces)
    try:
        date(year, month, day)
    except ValueError:
        return False
    return True

def is_valid_license_key(text: str) -> bool:
    if not isinstance(text, str) or len(text) != 10:
        return False
    if text[3] != "-" or text[8] != "-":
        return False
    letters = text[:3]
    digits = text[4:8]
    check = text[9]
    if any(ch not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" for ch in letters):
        return False
    if not digits.isascii() or not digits.isdigit() or not check.isascii() or not check.isdigit():
        return False
    total = sum(ord(ch) - ord("A") + 1 for ch in letters) + sum(int(ch) for ch in digits)
    return int(check) == total % 10

def apply_member_discount(subtotal_cents: int, is_member: bool) -> int:
    if is_member and subtotal_cents >= 5000:
        return subtotal_cents - (subtotal_cents * 10 // 100)
    return subtotal_cents

def shipping_fee(order_cents: int, expedited: bool) -> int:
    if expedited:
        return 1499
    return 0 if order_cents >= 7500 else 799

def commission_rate(monthly_sales_cents: int) -> int:
    if monthly_sales_cents >= 500000:
        return 8
    if monthly_sales_cents >= 100000:
        return 5
    return 2

def late_payment_fee(balance_cents: int, days_late: int) -> int:
    if balance_cents == 0 or days_late <= 5:
        return 0
    if days_late <= 30:
        return 500
    return 1500

def loyalty_points(purchase_cents: int, premium: bool) -> int:
    points = purchase_cents // 100
    return points * 2 if premium else points

def bulk_unit_price(quantity: int) -> int:
    if quantity == 0:
        return 0
    if quantity >= 50:
        return 950
    if quantity >= 10:
        return 1100
    return 1200

def cancellation_refund(ticket_cents: int, hours_before_event: int) -> int:
    if hours_before_event >= 72:
        return ticket_cents
    if hours_before_event >= 24:
        return ticket_cents // 2
    return 0
